#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(gridExtra);library(scales)})
set.seed(20260919)
root<-normalizePath(file.path(getwd(),"AD_CD33_reanalysis")); out<-file.path(root,"figures","publication"); dir.create(out,recursive=TRUE,showWarnings=FALSE)

cb<-c(WT_PBS="#0077BB",APPPS1_PBS="#EE7733",APPPS1_Control_ASO="#BBBBBB",APPPS1_CD33_ASO="#009988")
contrast_cols<-c(Disease="#CC3311",Control_ASO_effect="#7A7A7A",CD33_specific="#0077BB")
theme_pub<-theme_classic(base_size=9,base_family="Helvetica")+theme(plot.title=element_text(face="bold",size=10,hjust=0),plot.subtitle=element_text(size=8),axis.title=element_text(size=9),axis.text=element_text(size=7.5),legend.title=element_blank(),legend.text=element_text(size=7.5),strip.background=element_rect(fill="#F2F2F2",colour="black",linewidth=.3),strip.text=element_text(face="bold",size=8),plot.margin=margin(5,6,5,6))
lab_group<-c(WT_PBS="WT–PBS",APPPS1_PBS="APP/PS1–PBS",APPPS1_Control_ASO="APP/PS1–Control ASO",APPPS1_CD33_ASO="APP/PS1–CD33 ASO")
lab_tissue<-c(Hippocampus="Hippocampus",Frontal_cortex="Frontal cortex")
panel_tag<-theme(plot.tag=element_text(face="bold",size=11),plot.tag.position=c(0,1))
save_both<-function(p,name,w,h){ggsave(file.path(out,paste0(name,".pdf")),p,width=w,height=h,units="in",device="pdf");ggsave(file.path(out,paste0(name,".png")),p,width=w,height=h,units="in",dpi=600,bg="white")}

# ---------------- Figure 1 ----------------
manifest<-read.csv(file.path(root,"data","processed","sample_manifest_170.csv")); pca<-read.csv(file.path(root,"results","gene_level","pca_coordinates.csv"))
design_df<-data.frame(x=c(1,1,1,1,3,3,5,5),y=c(4,3,2,1,3.5,1.5,3.5,1.5),label=c("WT–PBS","APP/PS1–PBS","APP/PS1–Control ASO","APP/PS1–CD33 ASO","75 µg/day\nGSE74437","50 µg/day\nGSE74438","Hippocampus","Frontal cortex"),type=c(rep("group",4),rep("dose",2),rep("region",2)))
p1a<-ggplot()+annotate("segment",x=1.45,xend=2.55,y=2.5,yend=2.5,arrow=arrow(length=unit(.12,"in")),linewidth=.5)+annotate("segment",x=3.45,xend=4.55,y=2.5,yend=2.5,arrow=arrow(length=unit(.12,"in")),linewidth=.5)+geom_label(data=design_df,aes(x,y,label=label,fill=type),size=2.5,label.size=.25,label.padding=unit(.12,"lines"))+scale_fill_manual(values=c(group="#DDEBF7",dose="#E2F0D9",region="#FCE4D6"))+coord_cartesian(xlim=c(.3,5.8),ylim=c(.5,4.5),clip="off")+theme_void()+theme(legend.position="none",plot.title=element_text(face="bold",size=10))+labs(title="Experimental structure")
cnt<-as.data.frame(with(manifest,table(series,tissue,group))); names(cnt)[4]<-"n"; cnt$series<-factor(cnt$series,levels=c("GSE74437","GSE74438"),labels=c("75 µg/day","50 µg/day")); cnt$tissue<-factor(cnt$tissue,levels=c("Hippocampus","Frontal_cortex"),labels=c("Hippocampus","Frontal cortex")); cnt$group<-factor(cnt$group,levels=names(lab_group),labels=unname(lab_group))
p1b<-ggplot(cnt,aes(group,interaction(series,tissue,sep=" · "),fill=n))+geom_tile(colour="white",linewidth=.6)+geom_text(aes(label=n),size=2.6)+scale_fill_gradient(low="#F3F7FA",high="#0077BB")+labs(x=NULL,y=NULL,fill="n",title="Sample counts")+theme_pub+theme(axis.text.x=element_text(angle=32,hjust=1),legend.position="right")
pca$group<-factor(pca$group,levels=names(lab_group),labels=unname(lab_group)); pca$tissue<-factor(pca$tissue,levels=c("Hippocampus","Frontal_cortex"),labels=c("Hippocampus","Frontal cortex")); pca$series<-factor(pca$series,levels=c("GSE74437","GSE74438"),labels=c("75 µg/day","50 µg/day"))
p1c<-ggplot(pca,aes(PC1,PC2,colour=group,shape=series))+geom_point(size=1.8,alpha=.8)+facet_wrap(~tissue,scales="free")+scale_colour_manual(values=setNames(cb,unname(lab_group)))+scale_shape_manual(values=c(16,17))+labs(x="PC1",y="PC2",title="Expression-level quality control")+theme_pub+theme(legend.position="bottom",legend.box="vertical")
flow<-data.frame(x=1:6,y=1,label=c("Probe QC","Gene-level\ncollapse","Cohort × region\nmodels","Fixed-effect\nmeta-analysis","Pathway reversal\ntest","Human bulk +\nmicroglia validation"))
p1d<-ggplot(flow,aes(x,y))+geom_segment(data=data.frame(x=1:5,xend=2:6,y=1,yend=1),aes(x=x,xend=xend,y=y,yend=yend),inherit.aes=FALSE,arrow=arrow(length=unit(.08,"in")),linewidth=.4)+geom_label(aes(label=label),fill="#F2F2F2",label.size=.25,size=2.25)+coord_cartesian(xlim=c(.6,6.4),ylim=c(.75,1.25),clip="off")+theme_void()+labs(title="Prespecified analytical sequence")+theme(plot.title=element_text(face="bold",size=10))
fig1<-((p1a|p1b)/(p1c/p1d))+plot_annotation(tag_levels="A")&panel_tag; save_both(fig1,"Figure_1_study_design_and_QC",6.9,7.1)

# ---------------- Figure 2 ----------------
gl<-readRDS(file.path(root,"data","processed","gene_level_series.rds")); expr_rows<-list()
for(s in c("GSE74437","GSE74438")){i<-match("Cd33",rownames(gl[[s]]$expr)); d<-gl[[s]]$meta; d$expression<-as.numeric(gl[[s]]$expr[i,]); expr_rows[[s]]<-d}
cdexpr<-do.call(rbind,expr_rows); cdexpr$group<-factor(cdexpr$group,levels=names(lab_group),labels=unname(lab_group)); cdexpr$tissue<-factor(cdexpr$tissue,levels=c("Hippocampus","Frontal_cortex"),labels=c("Hippocampus","Frontal cortex")); cdexpr$series<-factor(cdexpr$series,levels=c("GSE74437","GSE74438"),labels=c("75 µg/day","50 µg/day"))
p2a<-ggplot(cdexpr,aes(group,expression,colour=group))+geom_boxplot(width=.62,outlier.shape=NA,fill="white",linewidth=.45)+geom_jitter(width=.13,size=1.25,alpha=.72)+facet_grid(tissue~series,scales="free_y")+scale_colour_manual(values=setNames(cb,unname(lab_group)))+labs(x=NULL,y="Cd33 expression (log2)",title="Cd33 expression across experimental groups")+theme_pub+theme(axis.text.x=element_text(angle=28,hjust=1),legend.position="none")
meta<-read.csv(file.path(root,"results","meta_analysis","fixed_effect_meta_by_region.csv")); cd<-meta[meta$gene_symbol=="Cd33" & meta$contrast%in%c("Disease","CD33_specific"),]; forest<-do.call(rbind,lapply(seq_len(nrow(cd)),function(i){z<-cd[i,];data.frame(tissue=z$tissue,contrast=z$contrast,estimate=c(z$logFC_75ug,z$logFC_50ug,z$meta_logFC),se=c(z$SE_75ug,z$SE_50ug,z$meta_SE),source=factor(c("75 µg/day","50 µg/day","Fixed-effect meta"),levels=c("75 µg/day","50 µg/day","Fixed-effect meta")),I2=z$I2)})); forest$lo<-forest$estimate-1.96*forest$se;forest$hi<-forest$estimate+1.96*forest$se;forest$tissue<-factor(forest$tissue,levels=c("Hippocampus","Frontal_cortex"),labels=c("Hippocampus","Frontal cortex"))
forest_plot<-function(ct,title){d<-forest[forest$contrast==ct,];ggplot(d,aes(estimate,source,shape=source))+geom_vline(xintercept=0,colour="grey65",linewidth=.4)+geom_errorbarh(aes(xmin=lo,xmax=hi),height=.13,linewidth=.45)+geom_point(size=2,colour=contrast_cols[ct])+facet_wrap(~tissue,scales="free_x")+scale_shape_manual(values=c(16,17,18))+labs(x="Log2 fold change (95% CI)",y=NULL,title=title)+theme_pub+theme(legend.position="none")}
p2b<-forest_plot("Disease","APP/PS1 disease effect");p2c<-forest_plot("CD33_specific","CD33-specific ASO effect")
sl<-forest[forest$contrast=="CD33_specific" & forest$source!="Fixed-effect meta",]; p2d<-ggplot(sl,aes(source,estimate,group=tissue,colour=tissue))+geom_hline(yintercept=0,colour="grey70")+geom_line(linewidth=.7)+geom_point(size=2.2)+scale_colour_manual(values=c("Hippocampus"="#0077BB","Frontal cortex"="#EE7733"))+labs(x=NULL,y="Cd33 log2 fold change",title="Larger suppression at 75 µg/day",subtitle="Meta-analysis heterogeneity: I² = 97.1% (hippocampus), 89.6% (frontal cortex)")+theme_pub+theme(legend.position="bottom")
fig2<-(p2a/(p2b|p2c)/p2d+plot_layout(heights=c(1.25,1,.75)))+plot_annotation(tag_levels="A")&panel_tag;save_both(fig2,"Figure_2_Cd33_cross_dose_effects",6.9,8.6)

# ---------------- Figure 3 ----------------
sp<-meta[meta$contrast=="CD33_specific",];sp$tissue_lab<-factor(sp$tissue,levels=c("Frontal_cortex","Hippocampus"),labels=c("Frontal cortex","Hippocampus"));sp$robust<-sp$meta_FDR<.05 & sp$direction_concordant & sp$I2<50
volc<-function(tis){d<-sp[sp$tissue==tis,];ggplot(d,aes(meta_logFC,-log10(pmax(meta_FDR,1e-300)),colour=robust))+geom_point(size=.65,alpha=.62)+geom_hline(yintercept=-log10(.05),linetype=2,colour="grey45")+scale_colour_manual(values=c(`FALSE`="#BDBDBD",`TRUE`="#0077BB"))+labs(x="Meta log2 fold change",y="−log10(FDR)",title=lab_tissue[tis],subtitle=sprintf("%d robust low-heterogeneity genes",sum(d$robust)))+theme_pub+theme(legend.position="none")}
p3a<-volc("Frontal_cortex");p3b<-volc("Hippocampus")
p3c<-ggplot(sp,aes(logFC_75ug,logFC_50ug,colour=robust))+geom_hline(yintercept=0,colour="grey75")+geom_vline(xintercept=0,colour="grey75")+geom_point(size=.65,alpha=.55)+geom_abline(slope=1,intercept=0,linetype=2,colour="black")+facet_wrap(~tissue_lab,scales="free")+scale_colour_manual(values=c(`FALSE`="#BDBDBD",`TRUE`="#0077BB"),labels=c("Other","FDR < 0.05, concordant, I² < 50%"))+labs(x="75 µg/day log2 fold change",y="50 µg/day log2 fold change",title="Cross-dose concordance")+theme_pub+theme(legend.position="bottom")
mc<-read.csv(file.path(root,"results","meta_analysis","meta_signal_counts.csv"));mc$tissue<-factor(mc$tissue,levels=c("Frontal_cortex","Hippocampus"),labels=c("Frontal cortex","Hippocampus"));mc$contrast<-factor(mc$contrast,levels=c("Disease","Control_ASO_effect","CD33_specific"),labels=c("Disease","Control ASO","CD33 specific"));p3d<-ggplot(mc,aes(contrast,low_heterogeneity_FDR05,fill=contrast))+geom_col(width=.65)+geom_text(aes(label=low_heterogeneity_FDR05),vjust=-.25,size=2.5)+facet_wrap(~tissue)+scale_fill_manual(values=c("Disease"=unname(contrast_cols["Disease"]),"Control ASO"=unname(contrast_cols["Control_ASO_effect"]),"CD33 specific"=unname(contrast_cols["CD33_specific"])))+expand_limits(y=max(mc$low_heterogeneity_FDR05)*1.1)+labs(x=NULL,y="Genes with FDR < 0.05,\nconcordant direction and I² < 50%",title="Low-heterogeneity signal counts")+theme_pub+theme(axis.text.x=element_text(angle=25,hjust=1),legend.position="none")
topgenes<-unique(unlist(lapply(split(sp,sp$tissue),function(d)head(d$gene_symbol[order(d$meta_FDR+rank(-abs(d$meta_logFC))*1e-12 & d$robust)],15))))
# deterministic fallback/top selection
topgenes<-unique(unlist(lapply(split(sp,sp$tissue),function(d){d<-d[d$robust,];head(d$gene_symbol[order(d$meta_FDR,-abs(d$meta_logFC))],15)})))
st<-read.csv(file.path(root,"results","meta_analysis","gene_level_stratum_contrasts.csv"));hm<-st[st$contrast=="CD33_specific" & st$gene_symbol%in%topgenes,c("gene_symbol","series","tissue","logFC")];hm$column<-paste(ifelse(hm$series=="GSE74437","75 µg/day","50 µg/day"),ifelse(hm$tissue=="Frontal_cortex","Frontal","Hippocampus"),sep=" · ");hm$gene_symbol<-factor(hm$gene_symbol,levels=rev(topgenes));p3e<-ggplot(hm,aes(column,gene_symbol,fill=logFC))+geom_tile(colour="white",linewidth=.25)+scale_fill_gradient2(low="#2166AC",mid="white",high="#B2182B",midpoint=0)+labs(x=NULL,y=NULL,fill="log2FC",title="Top robust CD33-specific genes")+theme_pub+theme(axis.text.x=element_text(angle=35,hjust=1),legend.position="right")
fig3<-((p3a|p3b)/(p3c|p3d)/p3e+plot_layout(heights=c(1,1,1.35)))+plot_annotation(tag_levels="A")&panel_tag;save_both(fig3,"Figure_3_gene_level_meta_analysis",6.9,9.0)

# ---------------- Figure 4 ----------------
pw<-read.csv(file.path(root,"results","pathway_reversal","pathway_reversal_all.csv"));sgn<-function(direction,p)ifelse(direction=="Up",1,-1)*-log10(pmax(p,1e-300));pw$disease_score<-sgn(pw$Direction_disease,pw$PValue_disease);pw$treatment_score<-sgn(pw$Direction_treatment,pw$PValue_treatment);pw$tissue_lab<-factor(pw$tissue,levels=c("Frontal_cortex","Hippocampus"),labels=c("Frontal cortex","Hippocampus"));pw$nominal<-pw$nominal_reversal
p4scatter<-function(coll){d<-pw[pw$collection==coll,];ggplot(d,aes(disease_score,treatment_score,colour=nominal))+geom_hline(yintercept=0,colour="grey70")+geom_vline(xintercept=0,colour="grey70")+geom_point(size=.75,alpha=.65)+facet_wrap(~tissue_lab,scales="free")+scale_colour_manual(values=c(`FALSE`="#BDBDBD",`TRUE`="#EE7733"),labels=c("Other","Nominal opposite-direction"))+labs(x="Disease signed −log10(P)",y="CD33-specific treatment signed −log10(P)",title=ifelse(coll=="GO_BP","GO biological process","KEGG"))+theme_pub+theme(legend.position="bottom")}
p4a<-p4scatter("GO_BP");p4b<-p4scatter("KEGG")
cats<-do.call(rbind,lapply(split(pw,interaction(pw$collection,pw$tissue)),function(d)data.frame(collection=d$collection[1],tissue=d$tissue[1],criterion=c("Disease FDR < 0.05","Treatment FDR < 0.05","Nominal reversal","Strict dual-FDR reversal"),n=c(sum(d$FDR_disease<.05),sum(d$FDR_treatment<.05),sum(d$nominal_reversal),sum(d$strict_reversal)))));cats$tissue<-factor(cats$tissue,levels=c("Frontal_cortex","Hippocampus"),labels=c("Frontal cortex","Hippocampus"));cats$criterion<-factor(cats$criterion,levels=rev(c("Disease FDR < 0.05","Treatment FDR < 0.05","Nominal reversal","Strict dual-FDR reversal")));p4c<-ggplot(cats,aes(n,criterion,fill=collection))+geom_col(position=position_dodge(width=.75),width=.65)+geom_text(aes(label=n),position=position_dodge(width=.75),hjust=-.15,size=2.3)+facet_wrap(~tissue,scales="free_x")+scale_fill_manual(values=c(GO_BP="#0077BB",KEGG="#EE7733"))+expand_limits(x=max(cats$n)*1.12)+labs(x="Number of pathways",y=NULL,title="Pathway counts by criterion")+theme_pub+theme(legend.position="bottom")
nom<-pw[pw$nominal_reversal,];nom$label<-paste(ifelse(nom$collection=="GO_BP","GO","KEGG"),nom$name,sep=": ");nom$maxFDR<-pmax(nom$FDR_disease,nom$FDR_treatment);nom$label<-factor(nom$label,levels=nom$label[order(nom$maxFDR,decreasing=TRUE)]);p4d<-ggplot(nom,aes(maxFDR,label,colour=tissue_lab))+geom_segment(aes(x=0,xend=maxFDR,y=label,yend=label),colour="grey75")+geom_point(size=2.2)+geom_vline(xintercept=.05,linetype=2)+scale_y_discrete(labels=function(x)sub(": ",":\n",x,fixed=TRUE))+scale_colour_manual(values=c("Frontal cortex"="#EE7733","Hippocampus"="#0077BB"))+labs(x="Maximum FDR",y=NULL,title="Nominal candidates")+theme_pub+theme(axis.text.y=element_text(size=7,lineheight=.9,margin=margin(r=5)),legend.position="bottom",plot.margin=margin(5,8,5,10))
fig4<-((p4a|p4b)/(p4c|p4d)+plot_layout(widths=c(.85,1.15)))+plot_annotation(tag_levels="A")&panel_tag;save_both(fig4,"Figure_4_pathway_reversal_test",6.9,7.2)

# ---------------- Figure 5 ----------------
h<-read.csv(file.path(root,"results","human_validation","human_region_gene_contrasts.csv"));g33<-read.csv(file.path(root,"results","human_validation","GSE33000_gene_contrasts.csv"));cdh<-rbind(g33[g33$human_symbol=="CD33",c("series","tissue","logFC","SE","P.Value")],h[h$human_symbol=="CD33",c("series","tissue","logFC","SE","P.Value")]);cdh$lo<-cdh$logFC-1.96*cdh$SE;cdh$hi<-cdh$logFC+1.96*cdh$SE;cdh$label<-paste(cdh$series,gsub("_"," ",cdh$tissue),sep=" · ");cdh$type<-ifelse(cdh$series=="GSE5281","Neuron-enriched","Bulk tissue");p5a<-ggplot(cdh,aes(logFC,reorder(label,logFC),colour=type,shape=type))+geom_vline(xintercept=0,colour="grey65")+geom_errorbarh(aes(xmin=lo,xmax=hi),height=.12)+geom_point(size=2)+scale_colour_manual(values=c("Bulk tissue"="#0077BB","Neuron-enriched"="#EE7733"))+scale_shape_manual(values=c(16,17))+labs(x="Human AD CD33 log2 fold change (95% CI)",y=NULL,title="Human CD33 effects")+theme_pub+theme(legend.position="bottom")
sig<-read.csv(file.path(root,"results","human_validation","mapped_robust_mouse_signatures.csv"));pm<-read.csv(file.path(root,"results","human_validation","primary_bulk_frontal_human_meta.csv"));sf<-sig[sig$tissue=="Frontal_cortex",];z<-merge(sf,pm,by="human_symbol",suffixes=c("_mouse","_human"));p5b<-ggplot(z,aes(meta_logFC_mouse,meta_logFC_human))+geom_hline(yintercept=0,colour="grey75")+geom_vline(xintercept=0,colour="grey75")+geom_point(size=1,alpha=.65,colour="#0077BB")+geom_smooth(method="lm",se=TRUE,linewidth=.6,colour="#CC3311",fill="#F4A582")+labs(x="Mouse CD33-ASO meta log2FC",y="Human AD bulk-frontal meta log2FC",title="Bulk-frontal cross-species test",subtitle="Spearman rho = 0.17, P = 0.0219")+theme_pub
co<-read.csv(file.path(root,"results","human_validation","cohort_signature_validation.csv"));mi<-read.csv(file.path(root,"results","human_validation","microglia_signature_validation.csv"));corplot<-rbind(data.frame(label=paste(co$series,gsub("_"," ",co$tissue),sep=" · "),rho=co$spearman_rho,n=co$n_mapped,type=ifelse(co$series=="GSE5281","Neuron-enriched","Bulk tissue")),data.frame(label=paste(mi$series,"microglia"),rho=mi$spearman_rho,n=mi$n_mapped,type="Microglia"));corplot$se<-1/sqrt(pmax(corplot$n-3,1));corplot$lo<-tanh(atanh(corplot$rho)-1.96*corplot$se);corplot$hi<-tanh(atanh(corplot$rho)+1.96*corplot$se);p5c<-ggplot(corplot,aes(rho,reorder(label,rho),colour=type,shape=type))+geom_vline(xintercept=0,colour="grey60")+geom_errorbarh(aes(xmin=lo,xmax=hi),height=.1)+geom_point(size=2)+scale_colour_manual(values=c("Bulk tissue"="#0077BB","Neuron-enriched"="#EE7733","Microglia"="#009988"))+labs(x="Spearman correlation (approximate 95% CI)",y=NULL,title="Signature correlations")+theme_pub+theme(legend.position="bottom")
short_tissue<-ifelse(co$tissue=="Frontal_cortex","FC","HC");enr<-rbind(data.frame(dataset=paste(co$series,short_tissue,sep=" · "),set="ASO down",direction=co$down_human_direction,p=co$down_P),data.frame(dataset=paste(co$series,short_tissue,sep=" · "),set="ASO up",direction=co$up_human_direction,p=co$up_P),data.frame(dataset=paste(mi$series,"MG"),set="ASO down",direction=mi$down_human_direction,p=mi$down_P),data.frame(dataset=paste(mi$series,"MG"),set="ASO up",direction=mi$up_human_direction,p=mi$up_P));enr$score<-ifelse(enr$direction=="Up",1,-1)*-log10(enr$p);p5d<-ggplot(enr,aes(score,reorder(dataset,score),colour=set,shape=set))+geom_vline(xintercept=0,colour="grey60")+geom_point(size=2)+facet_wrap(~set,scales="free_y")+scale_colour_manual(values=c("ASO down"="#2166AC","ASO up"="#B2182B"))+labs(x="Signed -log10(P): down < 0 < up",y=NULL,title="Directional enrichment")+theme_pub+theme(legend.position="none")
mg<-read.csv(file.path(root,"results","human_validation","microglia_gene_contrasts.csv"));make_mg<-function(series,mt,title){d<-mg[mg$series==series,];s<-sig[sig$tissue==mt,];q<-merge(s,d,by="human_symbol",suffixes=c("_mouse","_human"));rho<-cor(q$meta_logFC,q$logFC,method="spearman");p<-cor.test(q$meta_logFC,q$logFC,method="spearman",exact=FALSE)$p.value;ggplot(q,aes(meta_logFC,logFC))+geom_hline(yintercept=0,colour="grey75")+geom_vline(xintercept=0,colour="grey75")+geom_point(size=1,alpha=.62,colour="#009988")+geom_smooth(method="lm",se=FALSE,linewidth=.6,colour="#CC3311")+labs(x="Mouse CD33-ASO meta log2FC",y="Human microglia coefficient",title=title,subtitle=sprintf("Spearman rho = %.2f, P = %.3g",rho,p))+theme_pub}
p5e<-make_mg("GSE138852","Hippocampus","Entorhinal microglia: AD vs control");p5f<-make_mg("GSE243292","Frontal_cortex","DLPFC microglia: A/T pathology trend")
fig5<-((p5a|p5b)/(p5c|p5d)/(p5e|p5f))+plot_annotation(tag_levels="A")&panel_tag;save_both(fig5,"Figure_5_human_external_validation",6.9,9.5)

message("Five publication main figures written to: ",out)
